type agreementNativeAddressField struct {
	Line, Token       graph.Span
	Raw, Name, Folded string
	Owner             int
	Nodes             []int
	Code, Comment     bool
}
type agreementNativeAddressPart struct {
	Native agreementNativeOwnerSource
	Check  agreementNativeCheckSource
	Fields []agreementNativeAddressField
	Names  []string
}

// Every supported physical token keeps its complete native owner and literal
// roles; an inactive outside spelling cannot supply an erased declaration.
func agreementNativeAddressPartReading(body string) agreementNativeAddressPart {
	r := agreementNativeAddressPart{Native: agreementNativeOwnerReading(body)}
	r.Check = agreementNativeCheckReading(body, r.Native)
	r.Names = agreementCandidates(body, &agreementHTML{})
	for off := 0; off < len(body); {
		line, _, _ := strings.Cut(body[off:], "\n")
		raw := strings.TrimSuffix(line, "\r")
		name := render.BlockAddress(raw)
		if name != "" {
			at := off + strings.LastIndex(raw, name)
			f := agreementNativeAddressField{Line: graph.Span{Start: off, Stop: off + len(raw)}, Token: graph.Span{Start: at, Stop: at + len(name)}, Raw: raw, Name: name, Folded: graph.FoldFragment(name), Owner: -1}
			agreementNativeAddressOwners(&f, &r.Native)
			for _, c := range r.Native.Code {
				if c.Span.Start < f.Token.Stop && f.Token.Start < c.Span.Stop {
					f.Code = true
				}
			}
			for _, c := range r.Native.Comments {
				if c.Start < f.Token.Stop && f.Token.Start < c.Stop {
					f.Comment = true
				}
			}
			r.Fields = append(r.Fields, f)
		}
		off += len(line) + 1
	}
	return r
}
func agreementNativeAddressOwners(f *agreementNativeAddressField, native *agreementNativeOwnerSource) {
	for i := range native.Definitions {
		d := &native.Definitions[i]
		if d.Span.Start > f.Token.Start || f.Token.Stop > d.Span.Stop {
			continue
		}
		if f.Owner >= 0 {
			f.Owner = -2
			f.Nodes = nil
			return
		}
		f.Owner = i
		for n, node := range d.Nodes {
			for _, span := range node.Lines {
				if span.Start <= f.Token.Start && f.Token.Stop <= span.Stop {
					f.Nodes = append(f.Nodes, n)
					break
				}
			}
		}
	}
}
func agreementNativeAddressOwned(f *agreementNativeAddressField) bool {
	return f.Owner >= 0 && len(f.Nodes) != 0 && !f.Code && !f.Comment
}
func agreementNativeAddressShapes(fields []agreementNativeAddressField) []agreementNativeAddressField {
	result := slices.Clone(fields)
	for i := range result {
		f := &result[i]
		if !agreementNativeAddressOwned(f) {
			continue
		}
		raw := []byte(f.Raw)
		for at := f.Token.Start - f.Line.Start + 1; at < f.Token.Stop-f.Line.Start; at++ {
			raw[at] = '?'
		}
		f.Raw = string(raw)
		f.Name = "?"
		f.Folded = "?"
	}
	return result
}

type agreementNativeAddressChange struct{ Old, New string }
type agreementNativeAddressSource struct {
	Original, Projected agreementNativeAddressPart
	Body                string
	Changes             []agreementNativeAddressChange
	Shapes, AfterShapes []agreementNativeAddressField
	Valid               bool
}

// A private name changes only owned address bytes. Both complete native/check
// readings and every other field retain their declaration and physical position.
func agreementNativeAddressReading(body string) agreementNativeAddressSource {
	r := agreementNativeAddressSource{Original: agreementNativeAddressPartReading(body)}
	occupied := make(map[string]bool)
	for _, n := range r.Original.Names {
		if strings.ContainsAny(n, "|#]\r\n") || strings.HasSuffix(n, "\\") {
			return r
		}
		occupied[n] = true
	}
	renamed := make(map[string]string)
	projected := []byte(body)
	for i := range r.Original.Fields {
		f := &r.Original.Fields[i]
		if !agreementNativeAddressOwned(f) {
			continue
		}
		name := renamed[f.Folded]
		if name == "" {
			for _, ch := range []string{"q", "z", "v", "x", "w"} {
				candidate := "^" + strings.Repeat(ch, len(f.Name)-1)
				if !occupied[candidate] {
					name = candidate
					break
				}
			}
			if name == "" {
				return r
			}
			renamed[f.Folded] = name
			occupied[name] = true
			r.Changes = append(r.Changes, agreementNativeAddressChange{Old: f.Folded, New: name})
		}
		if len(name) != f.Token.Stop-f.Token.Start {
			return r
		}
		copy(projected[f.Token.Start:f.Token.Stop], name)
	}
	if len(r.Changes) == 0 {
		return r
	}
	r.Body = string(projected)
	r.Projected = agreementNativeAddressPartReading(r.Body)
	r.Shapes = agreementNativeAddressShapes(r.Original.Fields)
	r.AfterShapes = agreementNativeAddressShapes(r.Projected.Fields)
	r.Valid = cmp.Equal(r.Shapes, r.AfterShapes) && cmp.Equal(r.Original.Native, r.Projected.Native) && cmp.Equal(r.Original.Check, r.Projected.Check) && slices.Equal(r.Original.Check.Targets, judge.LinkTargets(body)) && slices.Equal(r.Projected.Check.Targets, judge.LinkTargets(r.Body))
	return r
}

type agreementNativeAddressReceipt struct {
	Page, Judge, Found bool
	Cut                string
}

// Every declared name gets an empty-note control before its public verdict.
// Record the whole namespace, including absent and inactive outside spellings.
func agreementNativeAddressPublic(t *testing.T, body string, a *agreementHTML, names []string) map[string]agreementNativeAddressReceipt {
	t.Helper()
	root := t.TempDir()
	contract, err := os.ReadFile("../schema/testdata/contract.toml")
	if err != nil {
		t.Fatal(err)
	}
	needle := `knowledge_dirs = ["Concepts", "Sources", "Maps", "Writing", "Synthesis", "Inbox"]`
	if strings.Count(string(contract), needle) != 1 {
		t.Fatal("native address contract declaration is not unique")
	}
	prepared := strings.Replace(string(contract), needle, `knowledge_dirs = ["Notes"]`, 1) + "\n[privacy]\nnever_egress_dirs = []\n"
	agreementWrite(t, root, schema.ContractRelPath, []byte(prepared))
	path, probePath := "Notes/address.md", "Notes/probe.md"
	agreementWrite(t, root, path, agreementEnvelope(t, ""))
	line := 1 + strings.Count(string(agreementEnvelope(t, "")), "\n")
	var probes []agreementProbe
	var lines []string
	for _, name := range names {
		if !strings.HasPrefix(name, "^") || strings.ContainsAny(name, "|#]\r\n") || strings.HasSuffix(name, "\\") {
			t.Fatal("native address public namespace is unspellable")
		}
		target := "Notes/address#" + name
		link, ok := graph.ParseWikilink(target)
		if !ok || link.Target != "Notes/address" || "^"+link.Block != name {
			t.Fatal("native address public name cannot be probed")
		}
		probes = append(probes, agreementProbe{Path: probePath, Line: line + len(lines), Target: target, ResolvedTo: path, Fragment: name, Rule: "link.block_missing"})
		lines = append(lines, "[["+target+"]]\n")
	}
	agreementWrite(t, root, probePath, agreementEnvelope(t, strings.Join(lines, "")))
	control := agreementMissing(t, root, probes)
	for _, p := range probes {
		if control[p.key()] != 1 {
			t.Fatal("native address empty control lacks exact missing receipt")
		}
	}
	agreementWrite(t, root, path, agreementEnvelope(t, body))
	missing := agreementMissing(t, root, probes)
	result := make(map[string]agreementNativeAddressReceipt)
	for _, p := range probes {
		cut, found := render.Excerpt(body, p.Fragment)
		result[p.Fragment] = agreementNativeAddressReceipt{Page: slices.Contains(a.Blocks, p.Fragment), Judge: missing[p.key()] == 0, Found: found, Cut: cut}
	}
	return result
}
func agreementNativeAddressNames(r *agreementNativeAddressSource, before, after *agreementHTML) []string {
	names := slices.Clone(r.Original.Names)
	names = append(names, r.Projected.Names...)
	names = append(names, before.Blocks...)
	names = append(names, after.Blocks...)
	absent := "^agreement-absent-0"
	for strings.Contains(r.Body, absent) || slices.Contains(names, absent) {
		absent += "x"
	}
	names = append(names, absent)
	slices.Sort(names)
	return slices.Compact(names)
}
func agreementNativeAddressEvidence(s *agreementNativeAddressSource, original, projected map[string]agreementNativeAddressReceipt, before, after *agreementHTML) bool {
	if !s.Valid || !cmp.Equal(before.Blocks, after.Blocks) {
		return false
	}
	selected := make(map[string]bool)
	for _, change := range s.Changes {
		selected[change.Old], selected[change.New] = true, true
		old, oldFound := original[change.Old]
		projectedReceipt, newFound := projected[change.New]
		if !oldFound || !newFound || old.Page || !old.Judge || !old.Found || projectedReceipt.Page || !projectedReceipt.Judge || !projectedReceipt.Found || original[change.New] != (agreementNativeAddressReceipt{}) || projected[change.Old] != (agreementNativeAddressReceipt{}) {
			return false
		}
		paired := false
		if len(s.Original.Fields) != len(s.Projected.Fields) {
			return false
		}
		for i := range s.Original.Fields {
			f, g := &s.Original.Fields[i], &s.Projected.Fields[i]
			if !agreementNativeAddressOwned(f) || f.Folded != change.Old {
				continue
			}
			for a := range strings.SplitSeq(old.Cut, "\n") {
				if strings.TrimSuffix(a, "\r") != f.Raw {
					continue
				}
				for b := range strings.SplitSeq(projectedReceipt.Cut, "\n") {
					if strings.TrimSuffix(b, "\r") == g.Raw {
						paired = true
					}
				}
			}
		}
		if !paired {
			return false
		}
	}
	if len(original) != len(projected) {
		return false
	}
	for name, value := range original {
		other, found := projected[name]
		if !found || (!selected[name] && value != other) {
			return false
		}
	}
	return true
}
func agreementNativeAddressSignatures(receipts map[string]agreementNativeAddressReceipt) map[string]int {
	result := make(map[string]int)
	for name, r := range receipts {
		for _, value := range []struct {
			name string
			has  bool
		}{{"judge", r.Judge}, {"excerpt", r.Found}} {
			if value.has == r.Page {
				continue
			}
			direction := value.name + "-only"
			if r.Page {
				direction = "page-not-" + value.name
			}
			f := agreementFailure{Property: "P3", Identity: "block-three-way", Fragment: name, Direction: direction, Multiplicity: 1, Cut: r.Cut, PagePresent: r.Page, JudgeAccepted: r.Judge, ExcerptFound: r.Found}
			result[agreementSignature(&f)]++
		}
	}
	return result
}
func agreementNativeAddressCurrent(failures []agreementFailure) map[string]int {
	result := make(map[string]int)
	for i := range failures {
		f := &failures[i]
		if f.Property == "setup" {
			return nil
		}
		if f.Property == "P3" {
			result[agreementSignature(f)]++
		}
	}
	return result
}

type agreementNativeAddressPayload struct {
	Body                         string
	Source                       agreementNativeAddressSource
	Names, Blocks, WitnessBlocks []string
	Original, Witness            map[string]agreementNativeAddressReceipt
	Signatures                   map[string]int
}

func agreementNativeAddressPayloadEvidence(p *agreementNativeAddressPayload) bool {
	a, w := agreementHTML{Blocks: p.Blocks}, agreementHTML{Blocks: p.WitnessBlocks}
	if !agreementNativeAddressEvidence(&p.Source, p.Original, p.Witness, &a, &w) || !cmp.Equal(p.Names, agreementNativeAddressNames(&p.Source, &a, &w)) || len(p.Original) != len(p.Names) || len(p.Witness) != len(p.Names) || !cmp.Equal(p.Signatures, agreementNativeAddressSignatures(p.Original)) {
		return false
	}
	for _, name := range p.Names {
		before, ok := p.Original[name]
		after, found := p.Witness[name]
		cut, has := render.Excerpt(p.Body, name)
		wcut, whas := render.Excerpt(p.Source.Body, name)
		if !ok || !found || before.Page != slices.Contains(p.Blocks, name) || after.Page != slices.Contains(p.WitnessBlocks, name) || before.Cut != cut || before.Found != has || after.Cut != wcut || after.Found != whas {
			return false
		}
	}
	return true
}
func agreementNativeAddressBudget(t *testing.T, body string, actual *agreementHTML, failures []agreementFailure) agreementNativeAddressPayload {
	t.Helper()
	source := agreementNativeAddressReading(body)
	if !source.Valid {
		return agreementNativeAddressPayload{}
	}
	_, witness := agreementIsolatedPage(t, agreementCase{Body: source.Body})
	names := agreementNativeAddressNames(&source, actual, &witness)
	original := agreementNativeAddressPublic(t, body, actual, names)
	projected := agreementNativeAddressPublic(t, source.Body, &witness, names)
	p := agreementNativeAddressPayload{Body: body, Source: source, Names: names, Blocks: slices.Clone(actual.Blocks), WitnessBlocks: slices.Clone(witness.Blocks), Original: original, Witness: projected, Signatures: agreementNativeAddressSignatures(original)}
	if !agreementNativeAddressPayloadEvidence(&p) || !cmp.Equal(p.Signatures, agreementNativeAddressCurrent(failures)) {
		return agreementNativeAddressPayload{}
	}
	return p
}
func agreementNativeAddressDifference(c agreementCase, f *agreementFailure, actual *agreementHTML, failures []agreementFailure, p *agreementNativeAddressPayload) (kind, authority, wrong string) {
	if c.Body != p.Body || c.Title != "" || len(c.Companions) != 0 || f.Property != "P3" || f.Identity != "block-three-way" || f.Tuple != (agreementCitation{}) || f.Multiplicity != 1 || f.PagePresent || !f.JudgeAccepted || !f.ExcerptFound || (f.Direction != "judge-only" && f.Direction != "excerpt-only") || f.Cut == "" || p.Signatures[agreementSignature(f)] != 1 {
		return "", "", ""
	}
	if !cmp.Equal(p.Source, agreementNativeAddressReading(c.Body)) || !cmp.Equal(p.Blocks, actual.Blocks) || !cmp.Equal(p.Signatures, agreementNativeAddressCurrent(failures)) || !agreementNativeAddressPayloadEvidence(p) {
		return "", "", ""
	}
	for _, change := range p.Source.Changes {
		if change.Old == f.Fragment {
			return "debt", "#1011 stage 5", "judge+excerpt"
		}
	}
	return "", "", ""
}

